<?php

declare(strict_types=1);

namespace Fb;

/**
 * Typed view of a `*.asset.php` file generated by @wordpress/scripts.
 */
final readonly class BuildAsset
{
	/**
	 * @param list<non-empty-string> $dependencies Script handles.
	 */
	public function __construct(
		public array $dependencies,
		public string $version,
	) {
	}

	public static function fromFile( string $file ): self
	{
		$data = require $file;

		if ( ! is_array( $data ) ) {
			throw new \UnexpectedValueException( "{$file}: expected an array." );
		}

		$dependencies = $data['dependencies'] ?? [];
		$version      = $data['version'] ?? '';

		if ( ! is_array( $dependencies ) || ! is_string( $version ) ) {
			throw new \UnexpectedValueException( "{$file}: unexpected shape." );
		}

		$handles = [];
		foreach ( $dependencies as $dependency ) {
			if ( is_string( $dependency ) && '' !== $dependency ) {
				$handles[] = $dependency;
			}
		}

		return new self( $handles, $version );
	}
}
